import Foundation

/// Surname and teams for an athlete chip, shown in the noun header card.
/// A team chip has no surname. A boxer can have a surname and no team line.
enum AthleteSheet {
    struct Card {
        let surname: String?
        let line: String?
    }

    static func card(category: NounBankCategory, word: String) -> Card? {
        table[key(category.rawValue, word)]
    }

    private static func key(_ category: String, _ word: String) -> String {
        category + "\u{1f}" + NounBankMark.normalize(word)
    }

